// Generates src/data.json from the repo's own committed record, so the
// dashboard can never drift from it:
//   src/openapi.json   the OpenAPI schema the app itself serves
//                      (regenerated by tools/gen_openapi.py); the
//                      endpoint register is derived from it
//   README.md          the API surface table (auth and purpose, cross-
//                      checked against the schema), the stated test
//                      count, the deployment status
//   tests/test_*.py    the test functions, counted per file
//   .github/workflows/ci.yml   the CI jobs
// The build fails when the counted tests disagree with the count the
// README states, when the README table and the schema disagree on the
// endpoint set or on which endpoints are secured, or when the record
// changes shape.
import { readFileSync, writeFileSync, readdirSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const root = join(here, "..", "..");
const readme = readFileSync(join(root, "README.md"), "utf-8");

function fail(message) {
  throw new Error(`gen-data: ${message}`);
}

// API surface: derived from the committed OpenAPI schema, with auth and
// purpose taken from the README table under "## API surface" and cross-
// checked against the schema (endpoint set and secured flag must agree).
const schema = JSON.parse(readFileSync(join(here, "..", "src", "openapi.json"), "utf-8"));
const normPath = (p) => p.replace(/\{[^}]+\}/g, "{}");
const schemaOps = new Map();
for (const [path, ops] of Object.entries(schema.paths)) {
  for (const [method, op] of Object.entries(ops)) {
    schemaOps.set(`${method.toUpperCase()} ${normPath(path)}`, {
      method: method.toUpperCase(),
      path,
      summary: op.summary || "",
      tags: op.tags || [],
      secured: Boolean(op.security && op.security.length),
      responses: Object.keys(op.responses || {}),
      parameters: (op.parameters || []).map((p) => ({
        name: p.name,
        where: p.in,
        required: Boolean(p.required),
      })),
    });
  }
}

const apiSection = readme.split("## API surface")[1];
if (!apiSection) fail("README has no API surface section");
const tableBlock = apiSection.split("\n## ")[0];
const readmeRows = new Map();
for (const line of tableBlock.split("\n")) {
  const row = line.match(/^\| (GET|POST|PATCH|DELETE) ([^|]+) \| ([^|]+) \| ([^|]+) \|$/);
  if (row) {
    readmeRows.set(`${row[1]} ${normPath(row[2].trim().split("?")[0])}`, {
      auth: row[3].trim(),
      purpose: row[4].trim(),
    });
  }
}
if (readmeRows.size < 20) fail(`expected at least 20 endpoint rows, parsed ${readmeRows.size}`);

const endpoints = [];
for (const [key, op] of schemaOps) {
  // GET / is the service index the app serves; the README table omits it,
  // so it is the one schema operation allowed no README row.
  if (key === "GET /") {
    endpoints.push({ ...op, auth: "none", purpose: "Service index: name, docs and health links" });
    continue;
  }
  const readmeRow = readmeRows.get(key);
  if (!readmeRow) fail(`schema operation ${key} has no README API table row`);
  const openAuth = readmeRow.auth === "none" || readmeRow.auth === "refresh token";
  if (op.secured === openAuth) {
    fail(`auth drift on ${key}: README says "${readmeRow.auth}" but schema secured=${op.secured}`);
  }
  endpoints.push({ ...op, auth: readmeRow.auth, purpose: readmeRow.purpose });
}
for (const key of readmeRows.keys()) {
  if (!schemaOps.has(key)) fail(`README API table row ${key} has no schema operation`);
}
const methodOrder = { GET: 0, POST: 1, PATCH: 2, DELETE: 3 };
endpoints.sort(
  (a, b) => a.path.localeCompare(b.path) || methodOrder[a.method] - methodOrder[b.method]
);
if (endpoints.length < 20) fail(`expected at least 20 endpoints, derived ${endpoints.length}`);

// Test evidence: the count the README states, checked against the tests.
const statedMatch = readme.match(/The suite \((\d+) tests\)/);
if (!statedMatch) fail("README does not state a test count");
const statedTests = Number(statedMatch[1]);

const testFiles = readdirSync(join(root, "tests"))
  .filter((name) => /^test_.*\.py$/.test(name))
  .sort();
const perFile = testFiles.map((name) => {
  const source = readFileSync(join(root, "tests", name), "utf-8");
  const count = (source.match(/^\s*(async )?def test_/gm) || []).length;
  return { file: `tests/${name}`, count };
});
const countedTests = perFile.reduce((sum, f) => sum + f.count, 0);
if (countedTests !== statedTests) {
  fail(`test count drift: README states ${statedTests}, tests/ holds ${countedTests}`);
}

// Deployment status: the bold status line in the README Deployment section.
const deploySection = readme.split("## Deployment")[1];
if (!deploySection) fail("README has no Deployment section");
const statusMatch = deploySection.match(/\*\*Status on ([0-9-]+): ([^*]+)\*\*/);
if (!statusMatch) fail("README Deployment section has no bold status line");

// CI jobs: the job keys of .github/workflows/ci.yml.
const ci = readFileSync(join(root, ".github", "workflows", "ci.yml"), "utf-8");
const jobsBlock = ci.split("\njobs:")[1];
if (!jobsBlock) fail("ci.yml has no jobs block");
const ciJobs = [...jobsBlock.matchAll(/^  ([a-z][a-z0-9-]*):$/gm)].map((m) => m[1]);
if (ciJobs.length < 2) fail(`expected at least 2 CI jobs, found ${ciJobs.length}`);

// Webhook events: the Literal declared in app/schemas.py.
const schemas = readFileSync(join(root, "app", "schemas.py"), "utf-8");
const eventsMatch = schemas.match(/WebhookEvent = Literal\[([^\]]+)\]/);
if (!eventsMatch) fail("app/schemas.py declares no WebhookEvent literal");
const webhookEvents = [...eventsMatch[1].matchAll(/"([^"]+)"/g)].map((m) => m[1]);
if (webhookEvents.length < 1) fail("no webhook events parsed from app/schemas.py");

const data = {
  endpoints,
  service: {
    title: schema.info.title,
    version: schema.info.version,
    description: schema.info.description,
  },
  tests: { total: countedTests, perFile },
  deployment: { date: statusMatch[1], status: statusMatch[2].trim() },
  ciJobs,
  webhookEvents,
};

writeFileSync(join(here, "..", "src", "data.json"), JSON.stringify(data, null, 2));
console.log(
  `data.json written: ${endpoints.length} endpoints, ${countedTests} tests, CI jobs ${ciJobs.join(", ")}`
);
